<?php
declare(strict_types=1);
require_once __DIR__.'/../src/audience_store.php';
$checks=0;
$expect=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$reject=static function(callable $call,string $message)use($expect):void{try{$call();}catch(InvalidArgumentException){$expect(true,$message);return;}throw new RuntimeException($message);};
$today=new DateTimeImmutable('2026-10-16',new DateTimeZone('America/Chicago'));
foreach(['last7'=>['2026-10-10','2026-10-16'],'week'=>['2026-10-05','2026-10-11'],'month'=>['2026-09-01','2026-09-30'],'quarter'=>['2026-07-01','2026-09-30'],'qtd'=>['2026-10-01','2026-10-15'],'ytd'=>['2026-01-01','2026-10-15']]as$preset=>$range)$expect(audienceCampaignDateRange($preset,$today)===$range,'Calendar preset '.$preset);
$expect(audienceCampaignDateRange('quarter',new DateTimeImmutable('2026-01-01'))===['2025-10-01','2025-12-31'],'Quarter crosses year boundary');
[$start,$end]=audienceCampaignPlannerRange('2026-02-18','month');$expect($start->format('Y-m-d')==='2026-01-26'&&$end->format('Y-m-d')==='2026-03-01','Month includes surrounding calendar days');
[$start,$end]=audienceCampaignPlannerRange('2026-10-16','week');$expect($start->format('Y-m-d')==='2026-10-12'&&$end->format('Y-m-d')==='2026-10-18','Week starts Monday');
$reject(fn()=>audienceCampaignDate('2026-02-30'),'Impossible dates rejected');
$reject(fn()=>audienceCampaignDate('2026-10-16T25:00',true),'Impossible times rejected');
$holidays=audienceCampaignHolidays(2026);$expect(($holidays['2026-11-26']??'')==='Thanksgiving','Movable holiday');
$expect(isset($holidays['2026-07-04']),'Fixed holiday');
$ab=audienceCampaignExperiment(['variables'=>['subject'=>['One','Two']]],'ab');$expect($ab['combinations']===2,'A/B pair');
$three=audienceCampaignExperiment(['variables'=>['from'=>['One','Two','Three']]]);$expect($three['combinations']===3,'A/B supports three variations');
$reject(fn()=>audienceCampaignExperiment(['variables'=>['subject'=>['Same','Same']]],'ab'),'Duplicate test values rejected');
$reject(fn()=>audienceCampaignExperiment(['variables'=>['subject'=>['A','B'],'from'=>['A','B']]],'ab'),'A/B only one variable');
$reject(fn()=>audienceCampaignExperiment(['variables'=>['subject'=>['A','B','C','D']]]),'More than three variations rejected');
$reject(fn()=>audienceCampaignExperiment(['variables'=>['subject'=>['A','B']]],'unsupported'),'Unsupported test kind rejected');
$reject(fn()=>audienceCampaignExperiment(['variables'=>['time'=>['2026-10-20T09:00','2026-10-20T12:00']],'test_percent'=>'50']),'Send time uses full recipient group');
$expect(!isset(audienceRuleCatalog([],[],[])['is_vip']),'VIP is not an available segment condition');
$expect(!str_contains(audienceConnectionOrder('is_vip','asc',[]),'is_vip'),'VIP sorting unavailable');
$expect(audienceLanguageOptions('en-US')['en-US']==='English (United States)'&&isset(audienceLanguageOptions('fil')['fil']),'Language choices preserve existing codes');
$reject(fn()=>audienceDesignWebFont('data:font/woff2;base64,'.base64_encode(str_repeat('x',80))),'Invalid font signature rejected');
$reject(fn()=>audienceDesignWebFont('data:font/woff2;base64,'.base64_encode('wOF2'.str_repeat("\0",44))),'Incomplete font header rejected');
$font='data:font/woff2;base64,'.base64_encode(file_get_contents(__DIR__.'/../src/assets/fonts/rubik-latin-700.woff2'));
$fontDesign=audienceDesignStarters()['newsletter']['design'];$fontDesign['styles']['webFont']=$font;
$expect(str_contains(audienceDesignHtml($fontDesign),'font-family:MOEDBrandFont,Arial!important'),'Embedded fonts retain inherited mobile font style');
$fontDesign['mode']='code';$fontDesign['code']='<html><head></head><body><p>Brand font</p></body></html>';
$expect(str_contains(audienceDesignHtml($fontDesign),'@font-face'),'Validated brand font survives the safe custom-code rendering boundary');
echo "Campaign completion validation: $checks checks passed.\n";
